Object.assign(SNIP,{});PRESET_NOTES["l12"]={"Ví dụ: Tổng lớn nhất của k số liên tiếp": "Vùng sáng là cửa sổ hiện tại. Mỗi bước: thêm a[i] bên phải, bớt a[i − k] bên trái. Tổng lớn nhất 13 (đoạn 4 6 3).", "Ví dụ: Đoạn ngắn nhất có tổng ≥ S": "r nới cửa sổ sang phải; khi tổng đã đủ S thì l thu hẹp từ trái để tìm đoạn ngắn hơn. Cả l và r chỉ đi tới, không lùi. Kết quả 2 (đoạn 4 3).", "Ví dụ: Chuỗi con dài nhất không lặp ký tự": "Khi thêm s[r] làm một ký tự xuất hiện hai lần, l tiến tới khi bỏ được bản cũ của ký tự đó. Cửa sổ luôn không có ký tự trùng. Kết quả 3 (abc).", "Lỗi: cửa sổ trượt với số âm": "Khi r = 3, tổng 4 − 3 + 1 + 5 = 7 ≥ 5, ghi nhận độ dài 4. Bỏ a[0] = 4 thì tổng còn 3 < 5 nên vòng while dừng, bỏ lỡ đoạn chỉ có số 5 (bỏ tiếp −3 thì tổng lại tăng). Với số âm, thu hẹp cửa sổ có thể làm tổng tăng: điều kiện đơn điệu không còn."};EX_HINTS["l12"]=[["Khởi tạo best bằng tổng cửa sổ đầu tiên (không phải 0: mọi số có thể âm).", "Tổng tới 10¹⁴: dùng long long."], ["Mọi số dương nên khi tổng đã ≥ S, thu hẹp từ trái chỉ làm tổng giảm: thu tới khi không còn đủ.", "Khởi tạo đáp án n + 1 (một giá trị không thể đạt) để biết trường hợp không có đoạn nào."], ["Chỉ s[r] vừa thêm có thể bị trùng, nên chỉ cần thu hẹp tới khi cnt[s[r]] trở về 1.", "s[r] − 'a' đổi ký tự thành chỉ số 0..25 của mảng đếm."]];
