RACE_X["race-a12"]=Object.assign(RACE_X["race-a12"]||{},{cs:["using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long best = long.MinValue;\n        for (int i = 0; i + k <= n; i++)\n        {\n            long s = 0;\n            for (int j = i; j < i + k; j++) s += a[j];\n            if (s > best) best = s;\n        }\n        Console.WriteLine(best);\n    }\n}", "using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long s = 0;\n        for (int i = 0; i < k; i++) s += a[i];\n        long best = s;\n        for (int i = k; i < n; i++)\n        {\n            s += a[i] - a[i - k];\n            if (s > best) best = s;\n        }\n        Console.WriteLine(best);\n    }\n}"]});
RACE_X["race-a12"]=Object.assign(RACE_X["race-a12"]||{},{py:["n, k = map(int, input().split())\na = list(map(int, input().split()))\nbest = None\nfor i in range(n - k + 1):\n    s = 0\n    for j in range(i, i + k):\n        s += a[j]\n    if best is None or s > best:\n        best = s\nprint(best)", "n, k = map(int, input().split())\na = list(map(int, input().split()))\ns = 0\nfor i in range(k):\n    s += a[i]\nbest = s\nfor i in range(k, n):\n    s += a[i] - a[i - k]\n    if s > best:\n        best = s\nprint(best)"]});
