const PR12=[{label:"Ví dụ: Tổng lớn nhất của k số liên tiếp",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {2, 5, 1, 4, 6, 3, -2, 7};\n    int k = 3, n = a.size();\n    int s = 0;\n    for (int i = 0; i < k; i++) s += a[i];\n    int best = s;\n    for (int i = k; i < n; i++) {\n        s += a[i] - a[i - k];\n        if (s > best) best = s;\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"vars",names:["s","best"]}],py:{code:"a = [2, 5, 1, 4, 6, 3, -2, 7]\nk = 3\nn = len(a)\ns = 0\nfor i in range(k):\n    s += a[i]\nbest = s\nfor i in range(k, n):\n    s += a[i] - a[i - k]\n    if s > best:\n        best = s\nprint(best)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 5, 1, 4, 6, 3, -2, 7 };\n        int k = 3, n = a.Length;\n        int s = 0;\n        for (int i = 0; i < k; i++) s += a[i];\n        int best = s;\n        for (int i = k; i < n; i++)\n        {\n            s += a[i] - a[i - k];\n            if (s > best) best = s;\n        }\n        Console.WriteLine(best);\n    }\n}"}},{label:"Ví dụ: Đoạn ngắn nhất có tổng ≥ S",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {2, 3, 1, 2, 4, 3};\n    int S = 7, n = a.size();\n    int l = 0, tong = 0, ngan = n + 1;\n    for (int r = 0; r < n; r++) {\n        tong += a[r];\n        while (tong >= S) {\n            if (r - l + 1 < ngan) ngan = r - l + 1;\n            tong -= a[l];\n            l++;\n        }\n    }\n    if (ngan == n + 1) cout << 0 << \"\\n\";\n    else cout << ngan << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["l","r"],range:["l","r"]},{type:"vars",names:["tong","ngan"]}],predict:[{line:13,v:"l",q:"Ô nào sắp bị bỏ khỏi cửa sổ? (bấm một cột)"}],py:{code:"a = [2, 3, 1, 2, 4, 3]\nS = 7\nn = len(a)\nl = 0\ntong = 0\nngan = n + 1\nfor r in range(n):\n    tong += a[r]\n    while tong >= S:\n        if r - l + 1 < ngan:\n            ngan = r - l + 1\n        tong -= a[l]\n        l += 1\nprint(0 if ngan == n + 1 else ngan)",predict:[{line:12,v:"l",q:"Ô nào sắp bị bỏ khỏi cửa sổ? (bấm một cột)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 3, 1, 2, 4, 3 };\n        int S = 7, n = a.Length;\n        int l = 0, tong = 0, ngan = n + 1;\n        for (int r = 0; r < n; r++)\n        {\n            tong += a[r];\n            while (tong >= S)\n            {\n                if (r - l + 1 < ngan) ngan = r - l + 1;\n                tong -= a[l];\n                l++;\n            }\n        }\n        if (ngan == n + 1) Console.WriteLine(0);\n        else Console.WriteLine(ngan);\n    }\n}",predict:[{line:16,v:"l",q:"Ô nào sắp bị bỏ khỏi cửa sổ? (bấm một cột)"}]}},{label:"Ví dụ: Chuỗi con dài nhất không lặp ký tự",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s = \"abcabcbb\";\n    int cnt[128] = {};\n    int l = 0, dai = 0;\n    for (int r = 0; r < (int)s.size(); r++) {\n        cnt[(int)s[r]]++;\n        while (cnt[(int)s[r]] > 1) {\n            cnt[(int)s[l]]--;\n            l++;\n        }\n        if (r - l + 1 > dai) dai = r - l + 1;\n    }\n    cout << dai << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["l","r"],range:["l","r"]},{type:"vars",names:["dai"]}],py:{code:"s = \"abcabcbb\"\ncnt = [0] * 128\nl = 0\ndai = 0\nfor r in range(len(s)):\n    cnt[ord(s[r])] += 1\n    while cnt[ord(s[r])] > 1:\n        cnt[ord(s[l])] -= 1\n        l += 1\n    if r - l + 1 > dai:\n        dai = r - l + 1\nprint(dai)",note:"ord(c) đổi ký tự thành mã số (a là 97) để dùng làm chỉ số của danh sách đếm. Cũng có thể dùng dict hoặc set (Chương 6)."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"abcabcbb\";\n        int[] cnt = new int[128];\n        int l = 0, dai = 0;\n        for (int r = 0; r < s.Length; r++)\n        {\n            cnt[s[r]]++;\n            while (cnt[s[r]] > 1)\n            {\n                cnt[s[l]]--;\n                l++;\n            }\n            if (r - l + 1 > dai) dai = r - l + 1;\n        }\n        Console.WriteLine(dai);\n    }\n}",note:"s[r] là một char; C# tự đổi char sang số (mã ký tự) khi dùng làm chỉ số, nên cnt[s[r]] đếm theo từng ký tự."}},{label:"Lỗi: cửa sổ trượt với số âm",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // tìm đoạn ngắn nhất có tổng >= 5, nhưng dãy có số âm\n    vector<int> a = {4, -3, 1, 5};\n    int S = 5, n = a.size();\n    int l = 0, tong = 0, ngan = n + 1;\n    for (int r = 0; r < n; r++) {\n        tong += a[r];\n        while (tong >= S && l <= r) {\n            if (r - l + 1 < ngan) ngan = r - l + 1;\n            tong -= a[l];\n            l++;\n        }\n    }\n    cout << ngan << \"\\n\";   // in 4, nhưng đáp án đúng là 1 (chỉ số 5)\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["l","r"],range:["l","r"]},{type:"vars",names:["tong","ngan"]}],py:{code:"# tìm đoạn ngắn nhất có tổng >= 5, nhưng dãy có số âm\na = [4, -3, 1, 5]\nS = 5\nn = len(a)\nl = 0\ntong = 0\nngan = n + 1\nfor r in range(n):\n    tong += a[r]\n    while tong >= S and l <= r:\n        if r - l + 1 < ngan:\n            ngan = r - l + 1\n        tong -= a[l]\n        l += 1\nprint(ngan)   # in 4, nhưng đáp án đúng là 1 (chỉ số 5)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        // tìm đoạn ngắn nhất có tổng >= 5, nhưng dãy có số âm\n        int[] a = { 4, -3, 1, 5 };\n        int S = 5, n = a.Length;\n        int l = 0, tong = 0, ngan = n + 1;\n        for (int r = 0; r < n; r++)\n        {\n            tong += a[r];\n            while (tong >= S && l <= r)\n            {\n                if (r - l + 1 < ngan) ngan = r - l + 1;\n                tong -= a[l];\n                l++;\n            }\n        }\n        Console.WriteLine(ngan);   // in 4, nhưng đáp án đúng là 1 (chỉ số 5)\n    }\n}"}}];
